contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        // Precondition: enough balance to fund non-reverting owner sends.
        require(address(this).balance >= value);

        // If this test contract is the owner, sending from it must succeed;
        // otherwise any non-owner attempt must revert. We structure the test
        // to observe one deciding call to sendMoney and assert the general rule.

        bool ownerIsTest = (address(this) == c.owner());

        bool reverted;
        if (ownerIsTest) {
            c.sendMoney{value: value}(target, value);
            reverted = false;
        } else {
            try c.sendMoney{value: value}(target, value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: for the onlyOwner-guarded sendMoney, success iff caller is owner.
        // Since every call to c in this test originates from this contract,
        // the expected outcome is characterized entirely by ownerIsTest.
        assert(ownerIsTest == !reverted);
    }

    receive() external payable {}
}

