contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint value) public payable {
        bool reverted;

        // Seed the contract with some balance so a successful withdraw is meaningful.
        (bool ok, ) = address(c).call{value: address(this).balance}("");
        require(ok);

        uint balBefore = address(c).balance;

        // The deciding call: withdraw(value) from the test contract.
        // Since this InvMutTest is the deployer/owner of c, it should succeed.
        if (caller == address(this)) {
            (bool sent, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", value));
            reverted = !sent;
        } else {
            // Non-owner call must revert; use try/catch on c.withdraw.
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balAfter = address(c).balance;

        // General rule: owner can always withdraw some amount <= balance without reverting;
        // non-owner calls always revert and leave c's balance unchanged.
        assert(
            (caller == address(this) && value <= balBefore && !reverted && address(c).balance == balBefore - value) ||
            (caller != address(this) && reverted && balAfter == balBefore)
        );
    }

    receive() external payable {}
}

