contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value) public {
        // Ensure the caller is not the owner by having the owner be the deployer (the test contract),
        // then call sendMoney from a different sender using a low-level call through c.
        // Since all calls on c from this function are from address(this), and owner is this contract,
        // we need another address to call sendMoney. We can create a minimal non-owner by using
        // a private helper via low-level call? But constraints say every call that changes c's state
        // must be a top-level statement, and we cannot use new deployments.
        // However, we can use the fact that msg.sender for c calls is always this contract.
        // To test non-owner behavior, we can exploit that c.owner is address(this) and we cannot
        // call as another address without cheatcodes. Therefore this rule cannot be tested directly
        // unless we use callbacks. We have a receive() callback but no way to invoke c from another address.
        // Given the constraints, we must design a rule that is testable with msg.sender = this contract.
        // We focus on owner's sendMoney behavior but differentiate from accepted rules.

        // Since we are the owner, sendMoney never reverts if enough balance. But we want a rule
        // about non-owner reverting. We can't easily become non-owner.

        // Alternative: we can test that if value > address(c).balance, the owner's sendMoney
        // call still succeeds (because .call does not revert on failure; it returns false).
        // But that rule was accepted? Not exactly.

        // Let's test a general rule: sendMoney by the owner never reverts regardless of value,
        // even if value exceeds c's balance, because low-level call does not propagate failure.
        // This is a different rule from accepted ones (which said it reverts exactly when c's balance < value or".

        // We'll capture before values.
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        // We call sendMoney with the given target and value. We are the owner.
        // But careful: if value > cBalanceBefore, the call should not revert because .call returns false.
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Assert that the call never reverts, and that c's balance decreases by at most value,
        // and owner/deposits unchanged.
        assert(!reverted && c.owner() == ownerBefore && c.depositsCount() == depositsBefore && address(c).balance >= cBalanceBefore - value);
    }

    receive() external payable {}
}

